      "signals": ["cpu-overprovisioned", "mem-overprovisioned"],
      "summary": "Both CPU and memory requests are significantly higher than actual usage; resources can be reduced."
    },
    {
      "workload": "demo/report-worker",
      "status": "ROUTINE",
      "signals": ["cpu-overprovisioned", "batch-pattern", "recurring-peak"],
      "summary": "Very low active fraction with periodic spikes indicates a batch job that can scale to zero when idle."
    }
  ]
}

{
  "workload": "demo/payment-service",
  "risk": "low",
  "diagnosis": "CPU usage peaks at 0.185 cores (p99) while the pod requests 2 cores; a request of ~0.22 cores (220 millicores) with ~20% headroom is sufficient. Memory usage peaks at 476.5 MiB, so a request of ~450 MiB and a limit of ~549 MiB (15% safety) covers the max. Reducing these resources will improve cluster efficiency without impacting performance.",
  "resources": {
    "cpu_request_m": 220,
    "mem_request_mi": 450,
    "mem_limit_mi": 549
  },
  "scaling": null,
  "follow_ups": []
}

{
  "workload": "demo/report-worker",
  "risk": "low",
  "diagnosis": "The report-worker is active only 2.8% of the time and shows a recurring CPU spike between 02:00‑03:00 (Asia/Colombo) reaching 1.74 cores. Memory usage peaks at 1323 MiB, so a 1.15× safety margin sets the limit to 1522 MiB. The recommended CPU request of 2.09 cores gives roughly 20% headroom over the active‑period p95 of 1.74 cores, while the memory request of 110 MiB satisfies the pod‑level p50 requirement.",
  "resources": {
    "cpu_request_m": 2092,
    "cpu_limit_m": null,
    "mem_request_mi": 110,
    "mem_limit_mi": 1522
  },
  "scaling": {
    "min_replicas": 0,
    "max_replicas": 2,
    "cron_windows": [
      {
        "start": "50 1 * * *",
        "end": "10 3 * * *",
        "desired_replicas": 1
      }
    ],
    "cpu_utilization_target": null
  },
  "follow_ups": []
}

{
  "workload": "demo/checkout-web",
  "risk": "medium",
  "diagnosis": "The pod CPU request is slightly low (0.5 cores) compared to the per‑pod p95 of 0.423 cores; adding ~20 % headroom suggests a request of ~0.51 cores (508 m). CPU over‑request is modest at 4.78 %. Weekday peaks from 09:00‑11:00 (Mon‑Fri) raise total CPU to ~2.78 cores, requiring about 6 replicas (vs the current 3). Memory usage is within limits, with no growth concerns.",
  "resources": {
    "cpu_request_m": 508,
    "cpu_limit_m": 1000,
    "mem_request_mi": 512,
    "mem_limit_mi": 768
  },
  "scaling": {
    "min_replicas": 3,
    "max_replicas": 6,
    "cron_windows": [
      {
        "start": "50 8 * * 1-5",
        "end": "10 11 * * 1-5",
        "desired_replicas": 6
      }
    ],
    "cpu_utilization_target": null
  },
  "follow_ups": []
}

{
  "sku": "F8s_v2",
  "nodes": 1,
  "rationale": "Burstable B-series nodes are avoided because the cluster runs sustained workloads (checkout-web, report-worker). The compute‑optimised F8s_v2 provides 8 vCPU and 16 GiB RAM in a single node, comfortably covering the post‑change demand of ~6 CPU cores and ~6 GiB memory (largest pod 2.1 CPU, 1.3 GiB). It costs $246.74 per month, the same as the two‑node F4s_v2 option but with lower node‑level overhead."
}
